PRAGMA foreign_keys = ON;

CREATE UNIQUE INDEX IF NOT EXISTS sim_accounts_id_owner_unique ON sim_accounts(id, owner_id);

CREATE TABLE IF NOT EXISTS sim_trade_history (
  id TEXT NOT NULL,
  version INTEGER NOT NULL CHECK (version > 0),
  account_id TEXT NOT NULL,
  owner_id TEXT NOT NULL,
  environment TEXT NOT NULL CHECK (environment IN ('SIMULATED', 'DEMO', 'LIVE')),
  source TEXT NOT NULL CHECK (source IN ('TradeRelayCity', 'Manual', 'Other')),
  record_type TEXT NOT NULL CHECK (record_type IN ('trade', 'attempt')),
  symbol TEXT NOT NULL,
  side TEXT CHECK (side IN ('BUY', 'SELL')),
  order_type TEXT,
  volume REAL,
  entry_time TEXT,
  exit_time TEXT,
  average_entry_price REAL,
  average_exit_price REAL,
  currency TEXT NOT NULL,
  gross_pnl REAL,
  commission REAL,
  swap REAL,
  other_costs REAL,
  net_pnl REAL,
  status TEXT NOT NULL,
  outcome TEXT NOT NULL CHECK (outcome IN ('closed_profit', 'closed_loss', 'closed_break_even', 'open_partial', 'broker_rejected', 'risk_blocked', 'skipped_hold', 'order_cancelled', 'order_expired', 'submission_unknown')),
  exit_reason TEXT,
  strategy TEXT,
  strategy_version TEXT,
  prompt_version TEXT,
  command_id TEXT,
  decision_id TEXT,
  broker_ticket TEXT,
  original_stop REAL,
  target REAL,
  requested_price REAL,
  slippage REAL,
  fills_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(fills_json)),
  timeline_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(timeline_json)),
  facts_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(facts_json)),
  observations_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(observations_json)),
  hypotheses_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(hypotheses_json)),
  missing_evidence_json TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(missing_evidence_json)),
  created_at TEXT NOT NULL,
  supersedes_version INTEGER,
  correction_reason TEXT,
  PRIMARY KEY (id, version),
  FOREIGN KEY (account_id, owner_id) REFERENCES sim_accounts(id, owner_id),
  FOREIGN KEY (id, supersedes_version) REFERENCES sim_trade_history(id, version)
);

CREATE INDEX IF NOT EXISTS sim_trade_history_account_time_idx ON sim_trade_history(account_id, entry_time DESC, id DESC, version DESC);
CREATE INDEX IF NOT EXISTS sim_trade_history_account_owner_idx ON sim_trade_history(account_id, owner_id, created_at DESC, id DESC);
CREATE INDEX IF NOT EXISTS sim_trade_history_ticket_idx ON sim_trade_history(account_id, broker_ticket, id);

